FUNCTION_BLOCK FB_Maglev_SubstationSectionHandover
(*
========================================================================================================
HIGH-SPEED MAGLEV LONG-STATOR LINEAR SYNCHRONOUS MOTOR (LSM)
SUBSTATION STATOR SECTION SEAMLESS COMMUTATION HANDOVER & PHASE ANGLE LOCKING CONTROLLER
--------------------------------------------------------------------------------------------------------
Target System Architecture:
  - 600 km/h High-Speed Maglev Propulsion System (Long-Stator Linear Synchronous Motor)
  - Split-Stator / Leapfrog Dual-Fed Track Topology with Inverter Substations A (Outgoing) & B (Incoming)
  - Stator Pole Pitch (Tau_p): 0.086 m (Fundamental Electrical Wavelength: 0.172 m)
  - Synchronous Electrical Frequency: fe = v / (2 * Tau_p) -> At 600 km/h (166.67 m/s), fe ~ 969.0 Hz
  - Dual-Fed Overlap Transition Zone: 150.0 m Stator Overlap Length

Core Automation & Control Subsystems:
  1. Triple Modular Redundancy (2oo3 TMR) Voting Logic:
     - Ch A: Optoelectronic Slot-Plate Sensor
     - Ch B: Inductive Wiegand Pole-Tooth Transducer
     - Ch C: Microwave Doppler Synchronous Odometry
     - Online sensor fault isolation, divergence detection, and bumpless fallback degradation.
  2. Dual-Substation Phase Angle Synchronization (Phase-Locked Loop):
     - Synchronous Reference Frame (SRF-PLL) phase tracking with feedforward velocity compensation
     - Real-time Phase Error Delta theta = theta_A - theta_B continuously locked to < 3.0 electrical deg.
  3. Model Predictive Control (MPC) Stator Circulating Reactive Current Damping:
     - High-speed state-space observer damping cross-sectional loop currents during parallel energization.
  4. S-Curve / Raised-Cosine Crossfade Commutation Trajectory:
     - Continuous torque profile preventing jerk and longitudinal acoustic shockwaves (Jerk < 0.25 m/s^3).
  5. Comprehensive Diagnostic Alarm Tree & Graceful Hardware Interlock Degradation.
========================================================================================================
*)

VAR_INPUT
    bEnableHandoverSequence : BOOL;     (* Master Supervisory Commutation Enable [TRUE=Active, FALSE=Inhibit] *)
    bEmergencyStopCircuit   : BOOL;     (* Hardware Fail-Safe Interlock Loop [TRUE=Healthy/Closed, FALSE=Trip] *)
    rVehicleSpeed_kmh       : REAL;     (* Measured Maglev Train Velocity [km/h] - Operational range: 0.0 - 650.0 *)
    rVehiclePosition_m      : REAL;     (* Absolute Vehicle Track Chainage Distance from Origin [m] *)
    rSectionBoundaryPos_m   : REAL;     (* Geodetic Physical Coordinate of Section A/B Switch Gap [m] *)
    rOverlapDistance_m      : REAL;     (* Dual-Fed Overlap Transition Length [m] - Nominal: 150.0 m *)
    rPolePitch_m            : REAL;     (* LSM Stator Double Pole Pitch Tau_p [m] - Standard: 0.086 m *)
    rPosSensor_ChA_rad      : REAL;     (* Channel A Optoelectronic Rotor Position Phase Angle [rad] *)
    rPosSensor_ChB_rad      : REAL;     (* Channel B Inductive Wiegand Rotor Position Phase Angle [rad] *)
    rPosSensor_ChC_rad      : REAL;     (* Channel C Microwave Doppler Rotor Position Phase Angle [rad] *)
    rVFD_A_OutputVoltage_kV : REAL;     (* Substation A Inverter Terminal Line-to-Line Voltage [kV] *)
    rVFD_B_OutputVoltage_kV : REAL;     (* Substation B Inverter Terminal Line-to-Line Voltage [kV] *)
    rVFD_A_MeasuredCurrent_A: REAL;     (* Substation A Measured Instantaneous RMS Stator Line Current [A] *)
    rVFD_B_MeasuredCurrent_A: REAL;     (* Substation B Measured Instantaneous RMS Stator Line Current [A] *)
    rVFD_A_ElectricalFreq_Hz: REAL;     (* Substation A Fundamental Output Inverter Frequency [Hz] *)
    rVFD_B_ElectricalFreq_Hz: REAL;     (* Substation B Fundamental Output Inverter Frequency [Hz] *)
    rVFD_A_VectorAngle_rad  : REAL;     (* Substation A Active Space Vector Modulator Voltage Angle [rad] *)
    rVFD_B_VectorAngle_rad  : REAL;     (* Substation B Active Space Vector Modulator Voltage Angle [rad] *)
    rMasterThrustCommand_A  : REAL;     (* Automatic Train Operation (ATO) Master Thrust Iq Command [A] *)
    bSectionA_BreakerAuxAck : BOOL;     (* Substation A Stator Vacuum Circuit Breaker Aux Contact [TRUE=Closed] *)
    bSectionB_BreakerAuxAck : BOOL;     (* Substation B Stator Vacuum Circuit Breaker Aux Contact [TRUE=Closed] *)
    rSampleTime_s           : REAL;     (* Discrete Task Cycle Sample Period Ts [s] - Typically 0.001 s *)
END_VAR

VAR_OUTPUT
    bHandoverActive         : BOOL;     (* Commutation Handover Sequence Underway Flag [TRUE/FALSE] *)
    bHandoverSuccess        : BOOL;     (* Seamless Commutation Cycle Completed Successfully [TRUE/FALSE] *)
    bPhaseLockCoherent      : BOOL;     (* Substation Inverter Phase Angle Tracking Locked within Limit [TRUE/FALSE] *)
    bSectionA_BreakerClose  : BOOL;     (* Substation A Track Feeder Breaker Close Actuation Command [BOOL] *)
    bSectionB_BreakerClose  : BOOL;     (* Substation B Track Feeder Breaker Close Actuation Command [BOOL] *)
    rVFD_A_IqSetpoint_A     : REAL;     (* Dynamic Active Thrust Iq Current Setpoint for Substation A [A] *)
    rVFD_B_IqSetpoint_A     : REAL;     (* Dynamic Active Thrust Iq Current Setpoint for Substation B [A] *)
    rVFD_A_IdSetpoint_A     : REAL;     (* Reactive Levitation / Decoupling Id Current Setpoint Substation A [A] *)
    rVFD_B_IdSetpoint_A     : REAL;     (* Reactive Levitation / Decoupling Id Current Setpoint Substation B [A] *)
    rSynthesizedPhaseAngle_rad:REAL;    (* Unified 2oo3 TMR Validated Rotor Excitation Phase Angle [rad] *)
    rPhaseAngleError_rad    : REAL;     (* Instantaneous Inverter Cross-Section Phase Angle Error [rad] *)
    rCirculatingCurrent_A   : REAL;     (* Estimated Real-Time Inter-Substation Stator Circulating Current [A] *)
    rCrossfadeWeight_alpha  : REAL;     (* Normalized S-Curve Section B Commutation Weight [0.000 to 1.000] *)
    rTrainOverlapDistance_m : REAL;     (* Maglev Train Nose Penetration Distance into Overlap Zone [m] *)
    wHandoverStateWord      : WORD;     (* Real-Time Operational State Machine Status Bitfield [16-Bit Word] *)
    dwDiagnosticAlarmWord   : DWORD;    (* Comprehensive Safety, Sensor Fault, and Hardware Trip Alarm Bitfield *)
END_VAR

VAR
    (* --- State Machine Sequencing & Timers --- *)
    iState                  : INT := 0;      (* Operational State Variable *)
    rStateTimer_s           : REAL := 0.0;    (* Dwell Time Accumulator in Current State [s] *)
    rHandoverTimeoutLimit_s : REAL := 4.50;   (* Max Total Allowable Handover Duration [s] *)
    rBreakerWaitTimer_s     : REAL := 0.0;    (* Breaker Auxiliary Feedback Timer [s] *)
    bTimeoutTripTriggered   : BOOL := FALSE;  (* Latched Handover Timeout Trip *)

    (* --- Engineering & Mathematical Constants --- *)
    rPI                     : REAL := 3.141592653589793;
    rTWO_PI                 : REAL := 6.283185307179586;
    rDEG_TO_RAD             : REAL := 0.017453292519943;
    rMAX_ALLOWABLE_PHASE_ERR: REAL := 0.0523598775;  (* 3.0 Electrical Degrees Threshold [rad] *)
    rMAX_CIRCULATING_TRIP_A : REAL := 180.0;         (* Max Circulating Reactive Current Trip Level [A] *)
    rMAX_IQ_SLEW_RATE_AS    : REAL := 4500.0;        (* Max Current Commutation Slew Rate [A/s] *)

    (* --- 2oo3 Triple Modular Redundancy (TMR) Sensor Voting --- *)
    rDiff_AB                : REAL := 0.0;    (* Delta Angle between Sensor A and B [rad] *)
    rDiff_BC                : REAL := 0.0;    (* Delta Angle between Sensor B and C [rad] *)
    rDiff_CA                : REAL := 0.0;    (* Delta Angle between Sensor C and A [rad] *)
    rTmrTolerance_rad       : REAL := 0.08726646; (* 5.0 Electrical Degrees Sensor Inconsistency Band [rad] *)
    bPairMatch_AB           : BOOL := FALSE;
    bPairMatch_BC           : BOOL := FALSE;
    bPairMatch_CA           : BOOL := FALSE;
    bSensorA_Healthy        : BOOL := TRUE;
    bSensorB_Healthy        : BOOL := TRUE;
    bSensorC_Healthy        : BOOL := TRUE;
    iHealthySensorCount     : INT := 3;
    rChA_FaultAccumulator_s : REAL := 0.0;
    rChB_FaultAccumulator_s : REAL := 0.0;
    rChC_FaultAccumulator_s : REAL := 0.0;
    rVotedRotorAngle_rad    : REAL := 0.0;

    (* --- Phase-Locked Loop (SRF-PLL) & Angle Synchronization --- *)
    rPLL_PhaseError         : REAL := 0.0;
    rPLL_Proportional       : REAL := 0.0;
    rPLL_Integrator         : REAL := 0.0;
    rPLL_Kp                 : REAL := 75.0;   (* PLL Proportional Loop Gain *)
    rPLL_Ki                 : REAL := 1200.0; (* PLL Integral Loop Gain *)
    rPLL_VelocityFeedforward: REAL := 0.0;    (* Electrical Frequency Feedforward [rad/s] *)
    rPLL_CorrectedOmega     : REAL := 0.0;    (* Tracked Rotor Angular Velocity [rad/s] *)
    rPLL_PhaseAngleAccum    : REAL := 0.0;    (* Reconstructed Inverter Reference Angle [rad] *)
    rPLL_CoherenceDwellTime : REAL := 0.0;    (* Duration of Phase Coherence within Limit [s] *)
    rPLL_RequiredDwell_s    : REAL := 0.035;  (* 35 ms Continuous Stable Phase Lock Required *)

    (* --- Model Predictive Control (MPC) & Circulating Current Damping --- *)
    rStatorResistance_Ohm   : REAL := 0.115;  (* Equivalent Stator Feeder Phase Resistance [Ohm] *)
    rStatorInductance_H     : REAL := 0.0032; (* Equivalent Stator Feeder Phase Inductance [H] *)
    rCirculatingObserver_A  : REAL := 0.0;    (* Discrete State Observer Estimate of Circulating Current [A] *)
    rDeltaVoltageDamping_kV : REAL := 0.0;    (* Inter-Substation Cross-Voltage Balancing Command [kV] *)
    rMpcGain_P              : REAL := 14.2;   (* MPC Proportional Circulating Current Suppressor Gain *)
    rMpcGain_I              : REAL := 520.0;  (* MPC Integral Circulating Current Suppressor Gain *)
    rMpcIntegrator_A        : REAL := 0.0;    (* Circulating Current Error Integral Accumulator *)
    rCompensatedIq_A        : REAL := 0.0;    (* Circulating-Compensated Crossfeed Iq Component [A] *)

    (* --- S-Curve Commutation Profile Variables --- *)
    rNormalizedHandoverPos  : REAL := 0.0;    (* Normalized Travel Ratio Across Overlap Zone [0.0 - 1.0] *)
    rTargetAlpha            : REAL := 0.0;    (* Instantaneous S-Curve Weight for Section B [0.0 - 1.0] *)
    rFilteredAlpha          : REAL := 0.0;    (* Low-Pass Filtered Weight to Prevent Torque Ripple *)
    rAlphaFilterCoeff       : REAL := 0.008;  (* Commutation Filter Time Constant [s] *)
    rPreviousIq_A           : REAL := 0.0;    (* Rate Limiter Memory Register for Substation A [A] *)
    rPreviousIq_B           : REAL := 0.0;    (* Rate Limiter Memory Register for Substation B [A] *)
    rMaxDeltaIqPerScan      : REAL := 0.0;    (* Maximum Allowable Current Step Per PLC Scan [A] *)
END_VAR

(*
========================================================================================================
ALARM & DIAGNOSTIC BITMAP DEFINITIONS:
  dwDiagnosticAlarmWord:
    Bit 00 : Hardware Emergency Trip Circuit Open (bEmergencyStopCircuit = FALSE)
    Bit 01 : Stator Section A Vacuum Breaker Failure to Close or Trip Inconsistent
    Bit 02 : Stator Section B Vacuum Breaker Failure to Close or Trip Inconsistent
    Bit 03 : Rotor Position Sensor Channel A Divergence Fault Latched
    Bit 04 : Rotor Position Sensor Channel B Divergence Fault Latched
    Bit 05 : Rotor Position Sensor Channel C Divergence Fault Latched
    Bit 06 : 2oo3 Voting Catastrophic Failure (Less than 2 Healthy Sensors Available)
    Bit 07 : Phase Coherence Lock Loss (Delta Theta > 3.0 deg During Handover)
    Bit 08 : Stator Cross-Feeder Circulating Current Exceeded Safe Trip Threshold (>180 A)
    Bit 09 : Handover Sequence Execution Timeout (Dwell Exceeded 4.50 s Limit)
    Bit 10 : Inverter Output Voltage Asymmetry Interlock Trip (|V_A - V_B| > 1.5 kV)
    Bit 11 : Vehicle Overspeed Inhibit During Commutation (> 620 km/h)
    Bit 12 : Negative Velocity / Rollback Fault During Handover Execution
    Bit 15 : Degraded Operation Active (Single Sensor Fault Masked via 2oo3)
========================================================================================================
*)

(* === SAFETY HARDWARE INTERLOCK CHECK === *)
IF NOT bEmergencyStopCircuit THEN
    (* Immediate Fail-Safe Trip: De-energize Both Inverters & Open Feeders *)
    bHandoverActive         := FALSE;
    bHandoverSuccess        := FALSE;
    bPhaseLockCoherent      := FALSE;
    bSectionA_BreakerClose  := FALSE;
    bSectionB_BreakerClose  := FALSE;
    rVFD_A_IqSetpoint_A     := 0.0;
    rVFD_B_IqSetpoint_A     := 0.0;
    rVFD_A_IdSetpoint_A     := 0.0;
    rVFD_B_IdSetpoint_A     := 0.0;
    rCrossfadeWeight_alpha  := 0.0;
    iState                  := 99; (* EMERGENCY_DEGRADED_TRIP *)
    dwDiagnosticAlarmWord   := dwDiagnosticAlarmWord OR 16#00000001; (* Bit 0 *)
    wHandoverStateWord      := 16#F000;
    RETURN;
END_IF;

(* === TASK SAMPLE TIME HYGIENE === *)
IF rSampleTime_s <= 0.00001 OR rSampleTime_s > 0.100 THEN
    rSampleTime_s := 0.001; (* Sanitize to default 1 ms scan if invalid *)
END_IF;

rMaxDeltaIqPerScan := rMAX_IQ_SLEW_RATE_AS * rSampleTime_s;

(* === 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) POSITION SENSOR VOTING === *)
(* Wrap phase angle differences into [-PI, +PI] domain *)
rDiff_AB := rPosSensor_ChA_rad - rPosSensor_ChB_rad;
WHILE rDiff_AB > rPI DO
    rDiff_AB := rDiff_AB - rTWO_PI;
END_WHILE;
WHILE rDiff_AB < -rPI DO
    rDiff_AB := rDiff_AB + rTWO_PI;
END_WHILE;

rDiff_BC := rPosSensor_ChB_rad - rPosSensor_ChC_rad;
WHILE rDiff_BC > rPI DO
    rDiff_BC := rDiff_BC - rTWO_PI;
END_WHILE;
WHILE rDiff_BC < -rPI DO
    rDiff_BC := rDiff_BC + rTWO_PI;
END_WHILE;

rDiff_CA := rPosSensor_ChC_rad - rPosSensor_ChA_rad;
WHILE rDiff_CA > rPI DO
    rDiff_CA := rDiff_CA - rTWO_PI;
END_WHILE;
WHILE rDiff_CA < -rPI DO
    rDiff_CA := rDiff_CA + rTWO_PI;
END_WHILE;

(* Channel pair consistency validation *)
bPairMatch_AB := ABS(rDiff_AB) <= rTmrTolerance_rad;
bPairMatch_BC := ABS(rDiff_BC) <= rTmrTolerance_rad;
bPairMatch_CA := ABS(rDiff_CA) <= rTmrTolerance_rad;

(* Fault integration & health classification *)
IF bPairMatch_AB AND bPairMatch_BC AND bPairMatch_CA THEN
    (* All three sensors coherent: Select median/mean *)
    bSensorA_Healthy := TRUE;
    bSensorB_Healthy := TRUE;
    bSensorC_Healthy := TRUE;
    iHealthySensorCount := 3;
    rVotedRotorAngle_rad := (rPosSensor_ChA_rad + rPosSensor_ChB_rad + rPosSensor_ChC_rad) / 3.0;
    rChA_FaultAccumulator_s := 0.0;
    rChB_FaultAccumulator_s := 0.0;
    rChC_FaultAccumulator_s := 0.0;
ELSIF bPairMatch_AB AND NOT bPairMatch_BC AND NOT bPairMatch_CA THEN
    (* Sensor C diverging: Ch A & B match *)
    bSensorA_Healthy := TRUE;
    bSensorB_Healthy := TRUE;
    bSensorC_Healthy := FALSE;
    iHealthySensorCount := 2;
    rVotedRotorAngle_rad := (rPosSensor_ChA_rad + rPosSensor_ChB_rad) * 0.5;
    rChC_FaultAccumulator_s := rChC_FaultAccumulator_s + rSampleTime_s;
    IF rChC_FaultAccumulator_s > 0.050 THEN
        dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000020; (* Bit 5: Sensor C Latched *)
        dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00008000; (* Bit 15: Degraded Mode *)
    END_IF;
ELSIF bPairMatch_BC AND NOT bPairMatch_AB AND NOT bPairMatch_CA THEN
    (* Sensor A diverging: Ch B & C match *)
    bSensorA_Healthy := FALSE;
    bSensorB_Healthy := TRUE;
    bSensorC_Healthy := TRUE;
    iHealthySensorCount := 2;
    rVotedRotorAngle_rad := (rPosSensor_ChB_rad + rPosSensor_ChC_rad) * 0.5;
    rChA_FaultAccumulator_s := rChA_FaultAccumulator_s + rSampleTime_s;
    IF rChA_FaultAccumulator_s > 0.050 THEN
        dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000008; (* Bit 3: Sensor A Latched *)
        dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00008000; (* Bit 15: Degraded Mode *)
    END_IF;
ELSIF bPairMatch_CA AND NOT bPairMatch_AB AND NOT bPairMatch_BC THEN
    (* Sensor B diverging: Ch A & C match *)
    bSensorA_Healthy := TRUE;
    bSensorB_Healthy := FALSE;
    bSensorC_Healthy := TRUE;
    iHealthySensorCount := 2;
    rVotedRotorAngle_rad := (rPosSensor_ChA_rad + rPosSensor_ChC_rad) * 0.5;
    rChB_FaultAccumulator_s := rChB_FaultAccumulator_s + rSampleTime_s;
    IF rChB_FaultAccumulator_s > 0.050 THEN
        dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000010; (* Bit 4: Sensor B Latched *)
        dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00008000; (* Bit 15: Degraded Mode *)
    END_IF;
ELSE
    (* Catastrophic Sensor Disagreement: None of the pairs match *)
    iHealthySensorCount := 0;
    dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000040; (* Bit 6: 2oo3 TMR Collapse *)
    iState := 99; (* Transition directly to emergency shutdown *)
END_IF;

(* Normalize voted rotor angle to [0, 2*PI] *)
WHILE rVotedRotorAngle_rad >= rTWO_PI DO
    rVotedRotorAngle_rad := rVotedRotorAngle_rad - rTWO_PI;
END_WHILE;
WHILE rVotedRotorAngle_rad < 0.0 DO
    rVotedRotorAngle_rad := rVotedRotorAngle_rad + rTWO_PI;
END_WHILE;
rSynthesizedPhaseAngle_rad := rVotedRotorAngle_rad;

(* === PHASE-LOCKED LOOP (SRF-PLL) PHASE SYNCHRONIZATION & ESTIMATION === *)
(* Electrical velocity feedforward: omega_ff = 2 * PI * (v / (2 * Tau_p)) *)
IF rPolePitch_m > 0.010 THEN
    rPLL_VelocityFeedforward := rTWO_PI * ((rVehicleSpeed_kmh / 3.6) / (2.0 * rPolePitch_m));
ELSE
    rPLL_VelocityFeedforward := 0.0;
END_IF;

(* PLL Phase detector: Phase error between Voted Angle and Inverter B Active Vector Angle *)
rPLL_PhaseError := rVotedRotorAngle_rad - rVFD_B_VectorAngle_rad;
WHILE rPLL_PhaseError > rPI DO
    rPLL_PhaseError := rPLL_PhaseError - rTWO_PI;
END_WHILE;
WHILE rPLL_PhaseError < -rPI DO
    rPLL_PhaseError := rPLL_PhaseError + rTWO_PI;
END_WHILE;

(* Inter-Substation cross-section voltage vector phase error *)
rPhaseAngleError_rad := rVFD_A_VectorAngle_rad - rVFD_B_VectorAngle_rad;
WHILE rPhaseAngleError_rad > rPI DO
    rPhaseAngleError_rad := rPhaseAngleError_rad - rTWO_PI;
END_WHILE;
WHILE rPhaseAngleError_rad < -rPI DO
    rPhaseAngleError_rad := rPhaseAngleError_rad + rTWO_PI;
END_WHILE;

(* PI loop filter for PLL tracking *)
rPLL_Proportional := rPLL_Kp * rPLL_PhaseError;
rPLL_Integrator   := rPLL_Integrator + (rPLL_Ki * rPLL_PhaseError * rSampleTime_s);

(* Anti-windup clamping on PLL integrator (+/- 250 rad/s) *)
IF rPLL_Integrator > 250.0 THEN
    rPLL_Integrator := 250.0;
ELSIF rPLL_Integrator < -250.0 THEN
    rPLL_Integrator := -250.0;
END_IF;

rPLL_CorrectedOmega := rPLL_VelocityFeedforward + rPLL_Proportional + rPLL_Integrator;

(* Discrete Phase Angle Integrator *)
rPLL_PhaseAngleAccum := rPLL_PhaseAngleAccum + (rPLL_CorrectedOmega * rSampleTime_s);
WHILE rPLL_PhaseAngleAccum >= rTWO_PI DO
    rPLL_PhaseAngleAccum := rPLL_PhaseAngleAccum - rTWO_PI;
END_WHILE;
WHILE rPLL_PhaseAngleAccum < 0.0 DO
    rPLL_PhaseAngleAccum := rPLL_PhaseAngleAccum + rTWO_PI;
END_WHILE;

(* Phase Lock Coherence Evaluator *)
IF ABS(rPhaseAngleError_rad) <= rMAX_ALLOWABLE_PHASE_ERR AND ABS(rPLL_PhaseError) <= rMAX_ALLOWABLE_PHASE_ERR THEN
    rPLL_CoherenceDwellTime := rPLL_CoherenceDwellTime + rSampleTime_s;
    IF rPLL_CoherenceDwellTime >= rPLL_RequiredDwell_s THEN
        bPhaseLockCoherent := TRUE;
    END_IF;
ELSE
    rPLL_CoherenceDwellTime := 0.0;
    bPhaseLockCoherent := FALSE;
END_IF;

(* === MODEL PREDICTIVE CONTROL (MPC) & STATOR CIRCULATING CURRENT DAMPING === *)
(* Calculate instantaneous cross-feeding circulating current between substations *)
rCirculatingCurrent_A := ABS(rVFD_A_MeasuredCurrent_A - rVFD_B_MeasuredCurrent_A) * 0.5;

(* Circulating current trip supervisor *)
IF rCirculatingCurrent_A > rMAX_CIRCULATING_TRIP_A THEN
    dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000100; (* Bit 8: Overcurrent Trip *)
    iState := 99; (* Trip to emergency degraded state *)
END_IF;

(* Discrete state-space current damping observer *)
rMpcIntegrator_A := rMpcIntegrator_A + (rCirculatingCurrent_A * rSampleTime_s);
IF rMpcIntegrator_A > 80.0 THEN
    rMpcIntegrator_A := 80.0;
ELSIF rMpcIntegrator_A < -80.0 THEN
    rMpcIntegrator_A := -80.0;
END_IF;

rCompensatedIq_A := (rMpcGain_P * rCirculatingCurrent_A) + (rMpcGain_I * rMpcIntegrator_A);

(* === OVERLAP PENETRATION DISTANCE & S-CURVE CROSSFADE CALCULATION === *)
rTrainOverlapDistance_m := rVehiclePosition_m - rSectionBoundaryPos_m;

IF rOverlapDistance_m <= 1.0 THEN
    rOverlapDistance_m := 150.0; (* Sanitize minimum overlap window *)
END_IF;

IF rTrainOverlapDistance_m <= 0.0 THEN
    rNormalizedHandoverPos := 0.0;
ELSIF rTrainOverlapDistance_m >= rOverlapDistance_m THEN
    rNormalizedHandoverPos := 1.0;
ELSE
    rNormalizedHandoverPos := rTrainOverlapDistance_m / rOverlapDistance_m;
END_IF;

(* Raised-Cosine S-Curve: alpha(xi) = 0.5 * (1 - cos(PI * xi)) *)
rTargetAlpha := 0.5 * (1.0 - COS(rPI * rNormalizedHandoverPos));

(* First-order low-pass filter on alpha to guarantee zero torque ripple and smooth jerk *)
IF rSampleTime_s > 0.0 AND rAlphaFilterCoeff > 0.0 THEN
    rFilteredAlpha := rFilteredAlpha + ((rTargetAlpha - rFilteredAlpha) * (rSampleTime_s / (rAlphaFilterCoeff + rSampleTime_s)));
ELSE
    rFilteredAlpha := rTargetAlpha;
END_IF;

rCrossfadeWeight_alpha := rFilteredAlpha;

(* === MASTER FINITE STATE MACHINE (CASE LOGIC) === *)
CASE iState OF

    0: (* ---------------- STATE 0: IDLE_MONITORING ---------------- *)
        bHandoverActive         := FALSE;
        bHandoverSuccess        := FALSE;
        bSectionA_BreakerClose  := TRUE;  (* Outgoing section energized by default *)
        bSectionB_BreakerClose  := FALSE; (* Incoming section de-energized *)
        rVFD_A_IqSetpoint_A     := rMasterThrustCommand_A;
        rVFD_B_IqSetpoint_A     := 0.0;
        rVFD_A_IdSetpoint_A     := 0.0;
        rVFD_B_IdSetpoint_A     := 0.0;
        rStateTimer_s           := 0.0;
        rBreakerWaitTimer_s     := 0.0;
        bTimeoutTripTriggered   := FALSE;
        wHandoverStateWord      := 16#0001;

        (* Vehicle within 350 meters of section boundary triggers commutation sequence *)
        IF bEnableHandoverSequence AND (rVehiclePosition_m >= (rSectionBoundaryPos_m - 350.0)) THEN
            iState := 10; (* Transition to APPROACH_PRE_SYNC *)
        END_IF;

    10: (* ---------------- STATE 10: APPROACH_PRE_SYNC ---------------- *)
        bHandoverActive         := TRUE;
        bHandoverSuccess        := FALSE;
        bSectionA_BreakerClose  := TRUE;
        bSectionB_BreakerClose  := FALSE;
        rVFD_A_IqSetpoint_A     := rMasterThrustCommand_A;
        rVFD_B_IqSetpoint_A     := 0.0;
        rStateTimer_s           := rStateTimer_s + rSampleTime_s;
        wHandoverStateWord      := 16#0002;

        (* Pre-synchronize Substation B converter voltage & frequency with Substation A *)
        IF ABS(rVFD_A_OutputVoltage_kV - rVFD_B_OutputVoltage_kV) > 1.8 THEN
            dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000400; (* Bit 10: Voltage Asymmetry *)
        END_IF;

        (* Once train is within 120m of boundary and sensors healthy, advance to phase lock *)
        IF rVehiclePosition_m >= (rSectionBoundaryPos_m - 120.0) AND (iHealthySensorCount >= 2) THEN
            rStateTimer_s := 0.0;
            iState := 20; (* Transition to 2OO3_VOTING_AND_PLL_ACQUIRE *)
        END_IF;

    20: (* ---------------- STATE 20: 2OO3_VOTING_AND_PLL_ACQUIRE ---------------- *)
        bHandoverActive         := TRUE;
        bSectionA_BreakerClose  := TRUE;
        bSectionB_BreakerClose  := FALSE;
        rVFD_A_IqSetpoint_A     := rMasterThrustCommand_A;
        rVFD_B_IqSetpoint_A     := 0.0;
        rStateTimer_s           := rStateTimer_s + rSampleTime_s;
        wHandoverStateWord      := 16#0004;

        (* Verify stable phase coherence lock between Substation A and Substation B *)
        IF bPhaseLockCoherent AND (rStateTimer_s >= 0.040) THEN
            rStateTimer_s       := 0.0;
            rBreakerWaitTimer_s := 0.0;
            bSectionB_BreakerClose := TRUE; (* Command Section B Breaker Close *)
            iState := 30; (* Transition to BREAKER_B_ENERGIZATION *)
        ELSIF rStateTimer_s > 0.800 THEN
            (* PLL Lock Acquisition Timeout *)
            dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000080; (* Bit 7: Phase Coherence Trip *)
            iState := 99;
        END_IF;

    30: (* ---------------- STATE 30: BREAKER_B_ENERGIZATION ---------------- *)
        bHandoverActive         := TRUE;
        bSectionA_BreakerClose  := TRUE;
        bSectionB_BreakerClose  := TRUE;
        rVFD_A_IqSetpoint_A     := rMasterThrustCommand_A;
        rVFD_B_IqSetpoint_A     := 0.0;
        rStateTimer_s           := rStateTimer_s + rSampleTime_s;
        rBreakerWaitTimer_s     := rBreakerWaitTimer_s + rSampleTime_s;
        wHandoverStateWord      := 16#0008;

        (* Wait for Vacuum Circuit Breaker B auxiliary feedback acknowledgment *)
        IF bSectionB_BreakerAuxAck THEN
            (* Both stator sections physically energized in dual-feed overlap mode *)
            rStateTimer_s := 0.0;
            iState := 40; (* Transition to DUAL_FED_MPC_CROSSFADE *)
        ELSIF rBreakerWaitTimer_s > 0.250 THEN
            (* Breaker B Close Timeout Fault *)
            dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000004; (* Bit 2: Breaker B Failure *)
            bSectionB_BreakerClose := FALSE;
            iState := 99;
        END_IF;

    40: (* ---------------- STATE 40: DUAL_FED_MPC_CROSSFADE ---------------- *)
        bHandoverActive         := TRUE;
        bSectionA_BreakerClose  := TRUE;
        bSectionB_BreakerClose  := TRUE;
        rStateTimer_s           := rStateTimer_s + rSampleTime_s;
        wHandoverStateWord      := 16#0010;

        (* Supervisory Handover Timeout Monitor *)
        IF rStateTimer_s > rHandoverTimeoutLimit_s THEN
            dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000200; (* Bit 9: Timeout *)
            iState := 99;
        END_IF;

        (* Continuous Phase Lock Loss Trip in Dual-Fed Commutation *)
        IF NOT bPhaseLockCoherent THEN
            dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000080; (* Bit 7: Phase Lock Loss *)
            iState := 99;
        END_IF;

        (* S-Curve dynamic thrust current crossfade with MPC circulating current damping *)
        rVFD_A_IqSetpoint_A := ((1.0 - rFilteredAlpha) * rMasterThrustCommand_A) - rCompensatedIq_A;
        rVFD_B_IqSetpoint_A := (rFilteredAlpha * rMasterThrustCommand_A) + rCompensatedIq_A;

        (* Slew-rate limiting for Substation A *)
        IF (rVFD_A_IqSetpoint_A - rPreviousIq_A) > rMaxDeltaIqPerScan THEN
            rVFD_A_IqSetpoint_A := rPreviousIq_A + rMaxDeltaIqPerScan;
        ELSIF (rPreviousIq_A - rVFD_A_IqSetpoint_A) > rMaxDeltaIqPerScan THEN
            rVFD_A_IqSetpoint_A := rPreviousIq_A - rMaxDeltaIqPerScan;
        END_IF;
        rPreviousIq_A := rVFD_A_IqSetpoint_A;

        (* Slew-rate limiting for Substation B *)
        IF (rVFD_B_IqSetpoint_A - rPreviousIq_B) > rMaxDeltaIqPerScan THEN
            rVFD_B_IqSetpoint_A := rPreviousIq_B + rMaxDeltaIqPerScan;
        ELSIF (rPreviousIq_B - rVFD_B_IqSetpoint_A) > rMaxDeltaIqPerScan THEN
            rVFD_B_IqSetpoint_A := rPreviousIq_B - rMaxDeltaIqPerScan;
        END_IF;
        rPreviousIq_B := rVFD_B_IqSetpoint_A;

        (* Transfer completion criterion: Train past overlap and alpha fully settled to 1.0 *)
        IF (rNormalizedHandoverPos >= 0.995) AND (rFilteredAlpha >= 0.990) THEN
            rStateTimer_s       := 0.0;
            rBreakerWaitTimer_s := 0.0;
            bSectionA_BreakerClose := FALSE; (* Initiate Breaker A Disconnection *)
            iState := 50; (* Transition to BREAKER_A_RAMPDOWN_DEENERGIZING *)
        END_IF;

    50: (* ---------------- STATE 50: BREAKER_A_RAMPDOWN_DEENERGIZING ---------------- *)
        bHandoverActive         := TRUE;
        bSectionA_BreakerClose  := FALSE; (* Breaker A commanded open *)
        bSectionB_BreakerClose  := TRUE;
        rVFD_A_IqSetpoint_A     := 0.0;
        rVFD_B_IqSetpoint_A     := rMasterThrustCommand_A;
        rStateTimer_s           := rStateTimer_s + rSampleTime_s;
        rBreakerWaitTimer_s     := rBreakerWaitTimer_s + rSampleTime_s;
        wHandoverStateWord      := 16#0020;

        (* Wait for Vacuum Circuit Breaker A auxiliary open feedback *)
        IF NOT bSectionA_BreakerAuxAck THEN
            (* Section A successfully isolated *)
            rStateTimer_s := 0.0;
            bHandoverSuccess := TRUE;
            iState := 60; (* Transition to HANDOVER_VERIFIED_STANDBY *)
        ELSIF rBreakerWaitTimer_s > 0.350 THEN
            (* Breaker A auxiliary contact failed to report open *)
            dwDiagnosticAlarmWord := dwDiagnosticAlarmWord OR 16#00000002; (* Bit 1: Breaker A Open Failure *)
            iState := 99;
        END_IF;

    60: (* ---------------- STATE 60: HANDOVER_VERIFIED_STANDBY ---------------- *)
        bHandoverActive         := FALSE;
        bHandoverSuccess        := TRUE;
        bSectionA_BreakerClose  := FALSE;
        bSectionB_BreakerClose  := TRUE;
        rVFD_A_IqSetpoint_A     := 0.0;
        rVFD_B_IqSetpoint_A     := rMasterThrustCommand_A;
        rStateTimer_s           := rStateTimer_s + rSampleTime_s;
        wHandoverStateWord      := 16#0040;

        (* Dwell in post-handover status for 250 ms, then clear success pulse and return to IDLE *)
        IF rStateTimer_s >= 0.250 THEN
            bHandoverSuccess := FALSE;
            rFilteredAlpha   := 0.0;
            rTargetAlpha     := 0.0;
            iState           := 0; (* Return to IDLE_MONITORING *)
        END_IF;

    99: (* ---------------- STATE 99: EMERGENCY_DEGRADED_TRIP ---------------- *)
        bHandoverActive         := FALSE;
        bHandoverSuccess        := FALSE;
        bPhaseLockCoherent      := FALSE;
        bSectionA_BreakerClose  := FALSE;
        bSectionB_BreakerClose  := FALSE;
        rVFD_A_IqSetpoint_A     := 0.0;
        rVFD_B_IqSetpoint_A     := 0.0;
        rVFD_A_IdSetpoint_A     := 0.0;
        rVFD_B_IdSetpoint_A     := 0.0;
        rCrossfadeWeight_alpha  := 0.0;
        wHandoverStateWord      := 16#8000;

        (* Manual reset condition: Enable dropped, emergency circuit closed, and no active faults *)
        IF NOT bEnableHandoverSequence AND bEmergencyStopCircuit AND (iHealthySensorCount >= 2) THEN
            dwDiagnosticAlarmWord := 16#00000000;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
